export function getArchetypeAgeReading(typeId,selectedStages=[]){
  const selected=[...new Set(selectedStages)].filter(id=>ageAwareArchetypes[typeId]?.[id]);
  return selected.map(id=>`${childAgeStages.find(stage=>stage.id===id)?.label}: ${ageAwareArchetypes[typeId][id].note}`).join('\n');
}
export function getArchetypeSituations(archetype,selectedStages=[]){
  if(!archetype)return [];
  const selected=[...new Set(selectedStages)].filter(id=>ageAwareArchetypes[archetype.id]?.[id]);
  const ageScenes=selected.map(id=>ageAwareArchetypes[archetype.id][id].scene);
  return [...ageScenes,...archetype.situations].slice(0,5);
}
export const questions=getQuestions(['school']);
export function scoreAnswers(answers,activeQuestions=questions){
  const scores=Object.fromEntries(typeIds.map(id=>[id,0]));
  for(const [i,choice] of answers.entries()){
    const option=activeQuestions[i]?.options[choice];
    if(!option)continue;
    for(const [id,weight] of Object.entries(option.scores))if(id in scores&&Number.isFinite(weight))scores[id]+=weight;
  }
  let winner=typeIds[0];
  for(const id of typeIds.slice(1))if(scores[id]>scores[winner])winner=id;
  return {archetype:archetypes.find(a=>a.id===winner),scores};
}

