const stageAstroNudge = stageIds => {
  const selected=(Array.isArray(stageIds)?stageIds:[]).filter(id=>id in astroByChildStage);
  return selected.length ? ` ${selected.map(id=>astroByChildStage[id]).join(' ')}` : '';
};
export const astroCombinations = Object.fromEntries(zodiacSigns.flatMap((sign,signIndex)=>archetypes.map(type=>[`${sign}|${type.id}`, astroCombinationLines[type.id][signIndex]])));
export function getAstroCombination(sign,typeId,childStageIds=[]){
  const reading=astroCombinations[`${sign}|${typeId}`];
  return reading ? `${reading}${stageAstroNudge(childStageIds)}` : null;
}
export function zodiacSign(value){
  if(!value)return null;
  const d=new Date(`${value}T12:00:00`);
  if(Number.isNaN(d.getTime())||d.toISOString().slice(0,10)!==value)return null;
  const m=d.getUTCMonth()+1,day=d.getUTCDate();
  if((m===3&&day>=21)||(m===4&&day<=19))return'Овен';
  if((m===4&&day>=20)||(m===5&&day<=20))return'Телец';
  if((m===5&&day>=21)||(m===6&&day<=20))return'Близнецы';
  if((m===6&&day>=21)||(m===7&&day<=22))return'Рак';
  if((m===7&&day>=23)||(m===8&&day<=22))return'Лев';
  if((m===8&&day>=23)||(m===9&&day<=22))return'Дева';
  if((m===9&&day>=23)||(m===10&&day<=22))return'Весы';
  if((m===10&&day>=23)||(m===11&&day<=21))return'Скорпион';
  if((m===11&&day>=22)||(m===12&&day<=21))return'Стрелец';
  if((m===12&&day>=22)||(m===1&&day<=19))return'Козерог';
  if((m===1&&day>=20)||(m===2&&day<=18))return'Водолей';
  return'Рыбы';
}
